// Tax-inclusive public monthly prices; never include provider IDs here.
export const PRICE_CONFIG = {
  IN: { symbol: "₹", amount: 299 },
  DEFAULT: { symbol: "$", amount: 5.99 },
} as const;
export const BILLING_PRICES = {
  USD: Math.round(PRICE_CONFIG.DEFAULT.amount * 100),
  INR: Math.round(PRICE_CONFIG.IN.amount * 100),
} as const;
export const PRICE_TAX_DESCRIPTION = "Includes applicable tax.";
export const PRICE_DESCRIPTION = `${PRICE_CONFIG.IN.symbol}${PRICE_CONFIG.IN.amount}/month for India; US${PRICE_CONFIG.DEFAULT.symbol}${PRICE_CONFIG.DEFAULT.amount}/month globally`;
export const ALLOWANCE_RESETS =
  "Daily allowances reset at midnight UTC. Free monthly allowances reset on the first day of each UTC calendar month; Premium monthly allowances follow the verified subscription billing period.";
export const NO_ROLLOVER = "Unused emails do not roll over.";
export const REFUND_POLICY =
  "No refunds, except where required by applicable law.";
export const SUPPORT_EMAIL = "[REDACTED_EMAIL]";
